style.css:
@-moz-document url-prefix("https://open.spotify.com") {
/* Soft pink global background */
  html, body {
    background-color: #e8a2c0 !important;
    color: #ffffff !important;
  }

  /* Sidebar soft pink */
  .Root__nav-bar,
  .main-yourLibraryX-library {
    background-color: #e8a2c0 !important;
    color: #ffffff !important;
    border: none !important;
  }
  .Root__nav-bar a,
  .main-yourLibraryX-library a {
    color: #ffffff !important;
  }

  /* Remove all dark borders and shadows */
  * {
    border-color: #e8a2c0 !important;
    box-shadow: none !important;
  }

  /* Leopard print header overlay */
  .Root__main-view::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 220px;
    background: url("https://i.imgur.com/Zn4CB0U.jpg") no-repeat center center;
    background-size: cover;
    opacity: 0.7;
    z-index: 999;
    pointer-events: none;
  }

  /* Remove Spotify gradient overlays */
  .main-entityHeader-overlay,
  .main-entityHeader-shadow {
    background: none !important;
  }

  /* Header text styling */
  .main-entityHeader-title,
  .main-entityHeader-subtitle {
    color: #ffffff !important;
    text-shadow: 1px 1px #c6538c !important;
    font-family: "Comic Sans MS", cursive, sans-serif !important;
  }

  /* Track list table with soft pink background */
  .main-trackList-trackList,
  .main-trackList-trackListRow {
    background-color: rgba(232, 162, 192, 0.2) !important;
    border: none !important;
  }
  .main-trackList-trackListRow:hover {
    background-color: rgba(232, 162, 192, 0.3) !important;
  }
  .main-trackList-trackListRow span,
  .main-trackList-trackListRow div,
  .main-trackList-trackListRow a {
    color: #ffffff !important;
  }

  /* Buttons in a deeper pink for contrast */
  button,
  .Button-sc-1dqy6lx-0 {
    background-color: #c6538c !important;
    color: #ffffff !important;
    border-radius: 8px !important;
    border: none !important;
  }

  /* Remove dark overlays at bottom */
  .main-view-container__scroll-node::after {
    background: none !important;
  }
  .main-rootlist-rootlistDivider {
    background: none !important;
  }

  /* Remove Hello Kitty overlay completely */
  .Root__main-view::after {
    content: none !important;
    background: none !important;
  }
}
